const stateIncidentFeeds = {
  OR: {
    name:'ODOT TripCheck',
    url:'https://services.arcgis.com/uUvqNMGPm7axC2dD/ArcGIS/rest/services/ODOT_Traffic_Incidents/FeatureServer/0/query',
    fields:'attributes_route,attributes_eventTypeName,attributes_eventSubTypeName,attributes_odotCategoryDescript,attributes_comments,attributes_beginMarker,attributes_incidentDirection,attributes_lastUpdated,attributes_startTime',
    order:'attributes_lastUpdated',
    report(a) {
      const detail = a.attributes_eventSubTypeName || a.attributes_eventTypeName || 'Road report';
      const category = [detail,a.attributes_eventTypeName,a.attributes_odotCategoryDescript].join(' ');
      const type = /chain condition/i.test(detail) ? 'chain' :
        /^(full closure|road closed|road closure|highway closed)$/i.test(detail) ? 'full' :
        /construction|roadwork|maintenance|lane closure/i.test(category) ? 'work' :
        /weather|winter|snow|ice/i.test(category) ? 'winter' : 'incident';
      return {type,title:[a.attributes_route,detail].filter(Boolean).join(' · '),
        place:a.attributes_beginMarker,direction:a.attributes_incidentDirection,
        description:a.attributes_comments,updated:a.attributes_lastUpdated,start:a.attributes_startTime};
    }
  },
  TN: {
    name:'TDOT SmartWay',
    url:'https://spatial.tdot.tn.gov/ArcGIS/rest/services/Smartway/Smartway_Events/FeatureServer/0/query',
    fields:'CD_ROAD_NAMES,CD_DIRECTION,EVENT_TYPE,EVENT_SUBTYPE,DESCRIPTION,HAS_CLOSURE,VEHICLE_IMPACT,OPPOSITE_VEHICLE_IMPACT,COUNTY_NAME,REVISED_DATE,START_DATE,END_DATE',
    order:'REVISED_DATE',
    bounds:[-90.4,34.9,-81.5,36.8],
    report(a) {
      if (a.END_DATE && a.END_DATE<Date.now()) return null;
      const detail=a.EVENT_SUBTYPE||a.EVENT_TYPE||'Road alert';
      const impact=[a.VEHICLE_IMPACT,a.OPPOSITE_VEHICLE_IMPACT].filter(Boolean);
      const type=a.HAS_CLOSURE===1&&impact.some(value=>/^(?:[a-z]+bound )?(?:closed|all lanes blocked)$/i.test(value))?'full':
        /construction|maintenance|roadwork|repair|project|paving/i.test(detail+' '+a.EVENT_TYPE)?'work':'incident';
      return {type,title:[a.CD_ROAD_NAMES,detail].filter(Boolean).join(' · '),place:a.COUNTY_NAME,
        direction:a.CD_DIRECTION,description:[a.DESCRIPTION,...impact].filter(Boolean).join(' · '),
        updated:a.REVISED_DATE,start:a.START_DATE,end:a.END_DATE};
    }
  },
  WA: {
    name:'WSDOT Travel Alerts',
    url:'https://data.wsdot.wa.gov/arcgis/rest/services/TravelInformation/TravelInfoRoadAlerts/FeatureServer/0/query',
    fields:'Road,RoadDirection,EventCategoryDescription,EventCategoryTypeDescription,HeadlineMessage,LastModifiedDate,RoadClosedFlag',
    order:'LastModifiedDate',
    report(a) {
      const detail = a.EventCategoryDescription || a.EventCategoryTypeDescription || 'Travel alert';
      const type = a.RoadClosedFlag === 1 ? 'full' :
        /construction|maintenance/i.test(a.EventCategoryTypeDescription) ? 'work' : 'incident';
      return {type,title:[a.Road,detail].filter(Boolean).join(' · '),direction:a.RoadDirection,
        description:a.HeadlineMessage,updated:a.LastModifiedDate};
    }
  }
};

function cleanRoadText(value) {
  return typeof value === 'string' ? value.replace(/<br\s*\/?>/gi,' ').replace(/<[^>]*>/g,'').trim().slice(0,2500) : '';
}

async function loadOtherStateRoads(code) {
  if (!/^[A-Z]{2}$/.test(code||'')) return json({error:'Invalid state.'},400);
  const feed = stateIncidentFeeds[code];
  const workFeed = stateWorkFeeds[code];
  if (!feed && !workFeed) return json({error:'An in-map feed is unavailable for this state.'},404);
  try {
    const query = feed && new URLSearchParams({where:'1=1',f:'json',outFields:feed.fields,outSR:'4326',
      orderByFields:feed.order+' DESC',resultRecordCount:'1000'});
    const data = await (await upstream(feed ? feed.url+'?'+query : workFeed,120)).json();
    if (!Array.isArray(data.features) || data.error) throw Error('Invalid road feed');
    const name = feed?.name || 'State DOT work-zone feed';
    const items = data.features.flatMap(feature => {
      const point = feed ? [feature.geometry?.x,feature.geometry?.y] : workZonePoint(feature.geometry);
      const [lon,lat] = point;
      if (!Number.isFinite(lat) || !Number.isFinite(lon) || Math.abs(lat)>90 || Math.abs(lon)>180 || lat===0 || lon===0) return [];
      const bounds=feed?.bounds;
      if(bounds&&(lon<bounds[0]||lat<bounds[1]||lon>bounds[2]||lat>bounds[3]))return [];
      const info = feed ? feed.report(feature.attributes || {}) : workZoneReport(feature.properties || {});
      if (!info) return [];
      return [{...info,lon,lat,source:name,title:cleanRoadText(info.title),place:cleanRoadText(info.place),
        direction:cleanRoadText(info.direction),description:cleanRoadText(info.description)}];
    });
    if (data.features.length && !items.length && feed) throw Error('Invalid incident locations');
    const lastUpdate = feed ? Math.max(0,...items.map(i=>i.updated||0)) : Date.parse(data.road_event_feed_info?.update_date||data.feed_info?.update_date);
    if (lastUpdate && Date.now()-lastUpdate > 24*3600000) {
      return json({error:name+' has not posted a recent update. Check the official map.'},503);
    }
    return json({items,checked:Date.now(),limited:!!data.exceededTransferLimit});
  } catch {
    return json({error:'Road feed unavailable. Check the official state map.'},502);
  }
}

function workZonePoint(g) {
  if (g?.type==='LineString'||g?.type==='MultiPoint') return g.coordinates?.[0] || [];
  if (g?.type==='MultiLineString') return g.coordinates?.[0]?.[0] || [];
  return g?.type==='Point' ? g.coordinates || [] : [];
}

function workZoneReport(p) {
  const core=p.core_details || {};
  const start=Date.parse(p.start_date),end=Date.parse(p.end_date);
  if (Number.isFinite(end) && end<Date.now() && p.is_end_date_verified) return null;
  return {type:'work',title:[core.road_names?.join?.(', '),'Work zone'].filter(Boolean).join(' · '),
    direction:core.direction,description:core.description,updated:Date.parse(core.update_date)||null,
    start:Number.isFinite(start)?start:null,end:Number.isFinite(end)?end:null};
}

const json=(data,status=200)=>new Response(JSON.stringify(data),{status,headers:{'Content-Type':'application/json','Cache-Control':'no-store'}});
