async function upstream(url,ttl=300){const r=await fetch(url,{headers:{'User-Agent':ua,'Accept':'application/json'},signal:AbortSignal.timeout(30000),cf:{cacheTtl:ttl,cacheEverything:true}});if(!r.ok)throw Error('Provider returned '+r.status);return r}
